+  }
+
+  @Test
+  void stopsAtNullCause() {
+    IllegalArgumentException error = new IllegalArgumentException("no cause");
+
+    assertThat(CauseUnwrapper.unwrapCause(error, unused -> true)).isSameAs(error);
+  }
